import sys

def solve(n, arr, queries):
    sorted_vals = sorted(set(arr)); rank = {v:i+1 for i,v in enumerate(sorted_vals)}
    m = len(sorted_vals); arr_r = [rank[v] for v in arr]
    SIZE = (n+1)*20
    lc = [0]*SIZE; rc = [0]*SIZE; cnt = [0]*SIZE; nid = [1]
    def new_node(): n=nid[0]; nid[0]+=1; return n
    def build(l, r):
        node = new_node()
        if l==r: return node
        mid=(l+r)//2; lc[node]=build(l,mid); rc[node]=build(mid+1,r); return node
    def update(prev, l, r, pos):
        node=new_node(); lc[node]=lc[prev]; rc[node]=rc[prev]; cnt[node]=cnt[prev]+1
        if l==r: return node
        mid=(l+r)//2
        if pos<=mid: lc[node]=update(lc[prev],l,mid,pos)
        else: rc[node]=update(rc[prev],mid+1,r,pos)
        return node
    def query(ln, rn, l, r, k):
        if l==r: return l
        mid=(l+r)//2; left_cnt=cnt[lc[rn]]-cnt[lc[ln]]
        if k<=left_cnt: return query(lc[ln],lc[rn],l,mid,k)
        else: return query(rc[ln],rc[rn],mid+1,r,k-left_cnt)
    roots=[build(1,m)]
    for v in arr_r: roots.append(update(roots[-1],1,m,v))
    out=[]
    for l,r,k in queries:
        rank_ans=query(roots[l-1],roots[r],1,m,k)
        out.append(str(sorted_vals[rank_ans-1]))
    return "\n".join(out)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    arr = list(map(int, data[idx:idx+n])); idx += n
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        l,r,k = int(data[idx]),int(data[idx+1]),int(data[idx+2]); idx+=3
        queries.append((l,r,k))
    print(solve(n, arr, queries))

